import axios from "axios";

let ISDEV = false;
//
if (process.env.VUE_APP_AXIOSHOST) {
    ISDEV = true;
    axios.defaults.baseURL = process.env.VUE_APP_AXIOSHOST
}

// Anti Forgery Token for CF API
let AntiForgeryInterceptorId = null;
function InterceptForAntiForgery()
{
    if (AntiForgeryInterceptorId !== null) {
        axios.interceptors.request.eject(AntiForgeryInterceptorId);
    }
    AntiForgeryInterceptorId = axios.interceptors.request.use((config) => {
        const antiForgeryToken = window.AntiForgeryToken;
        const authHeader = {};
        config.withCredentials = true;
        config.headers = {
            ...config.headers,
            ...authHeader,
            "content-type": "application/json; charset=utf-8",
            "__RequestVerificationToken": antiForgeryToken
        };
        return config;
    });
}
function RefreshAntiForgeryToken() {
    axios.get('/RefreshToken')
        .then(response => {
            if (response.data && response.data.token) {
                window.AntiForgeryToken = response.data.token;
                InterceptForAntiForgery();
                console.log("Token refreshed successfully");
            }
        })
        .catch(error => {
            console.error("Failed to refresh token", error);
        });
}
async function PerformSensitiveOperation() {
    try {
        await RefreshAntiForgeryToken();
    } catch (error) {
        console.error("Could not refresh token:", error);
    }
}
InterceptForAntiForgery();
setInterval(RefreshAntiForgeryToken, 15 * 60 * 1000);
// END Anti Forgery Token for CF API

